CREATE TABLE IF NOT EXISTS zone_pokemon(zone_id TEXT, dex INTEGER, name TEXT, type TEXT, rarity TEXT);
CREATE TABLE IF NOT EXISTS content_version(id INTEGER PRIMARY KEY AUTOINCREMENT, subject_id TEXT, built_at TEXT, agent TEXT, source_notes TEXT, status TEXT);
